function codecs(){const project=Reflect.get(owner,'block2dSnapshotToSqliteDatabase'),restore=Reflect.get(owner,'block2dSnapshotFromSqliteDatabase');expect(typeof project).toBe('function');expect(typeof restore).toBe('function');return{project,restore};}
for(const raw of laws.binary64Bits)test('Block2d complete owned IEEE word '+raw,async()=>{expect(new Ajv({strict:true}).compile(laws.wordSchema)({bits:raw})).toBe(true);const bytes=Buffer.from(raw,'hex');expect(new DataView(bytes.buffer,bytes.byteOffset,8).getBigUint64(0)).toBe(BigInt('0x'+raw));const value=specimen(raw);expect(owner.parseBlock2dSnapshot(value)).toEqual(value);const{project,restore}=codecs(),database=await project(value),db=Database.deserialize(await exportSqliteDatabase(database),{safeIntegers:true});try{expect(db.query('PRAGMA integrity_check').get()).toEqual({integrity_check:'ok'});expect(db.query('PRAGMA foreign_key_check').all()).toEqual([]);for(const[name,count]of Object.entries(laws.tableRowCounts))expect(db.query('SELECT COUNT(*) AS count FROM '+name).get()).toEqual({count:BigInt(count)});expect(await restore(await importSqliteDatabase(db.serialize()))).toEqual(value);db.query('UPDATE block2_meta SET description=?').run('independent\0😀');expect(await restore(await importSqliteDatabase(db.serialize()))).toEqual({...value,meta:{description:'independent\0😀'}});}finally{db.close();}});
